[3721] = { en = "An OOX of Your Own", tier = 4,
  t = "Een eigen OOX",
  c = "Je hebt drie van mijn OOX-zoekrobots teruggevonden! Je hebt veel meer gedaan dan nodig was, dus ik geef je iets speciaals voor al je hulp. Het is een kleine versie van precies dezelfde robot die je inmiddels kent en waar je van houdt: de OOX!$B$BNormaal zou ik niemand zo'n mogelijk dodelijk apparaat geven, maar je hebt me echt geholpen. En bovendien: de gevechtsfuncties en de zoeklogica van deze zijn uitgeschakeld.$B$BVerder is het gewoon een echte OOX, zowaar!",
  g = { {"OOX-zoekrobots", "OOX homing robots (zoekrobot)"}, {"teruggevonden", "recovered (terugvinden)"}, {"inmiddels", "by now"}, {"dodelijk", "lethal, deadly"}, {"apparaat", "device"}, {"bovendien", "besides, moreover"}, {"gevechtsfuncties", "combat mechanisms (gevechtsfunctie)"}, {"zoeklogica", "homing logic"}, {"uitgeschakeld", "disabled (uitschakelen)"}, {"zowaar", "by golly, actually"} },
},

[3788] = { en = "Jonespyre's Request", tier = 4,
  t = "Het verzoek van Jonespyre",
  d = "Neem me niet kwalijk, vriend...$B$BEen collega van mij wil graag met je praten over het onderzoek dat je samen met de Cenarion Circle doet. Hij is een druïde en heet Quintis Jonespyre. Hij woont hier in Feathermoon Stronghold. Hij wil met je overleggen over morrowgrain... en hij wil heel graag dat de Arch Druid niets van ons gesprek te horen krijgt.$B$BAls je interesse hebt, praat dan met hem. Zodra je dat doet, wordt alles vast duidelijk.",
  o = "Praat met Quintis Jonespyre in Feathermoon Stronghold.",
  c = "Dank je wel dat je gekomen bent, vermoeide reiziger! Laat me mezelf voorstellen: ik ben Quintis Jonespyre, druïde en nederige dienaar van Malfurion en de Cenarion Circle. Mijn collega's (General Shandris Feathermoon en het Protectorate - misschien heb je van ons gehoord) en ik wilden met je praten over het werk dat je voor Fandral Staghelm in Darnassus doet.$B$BVoordat we verder gaan, wil ik je vragen om ons gesprek onder ons te houden. Als je daar geen probleem mee hebt, kunnen we doorgaan.",
  g = { {"verzoek", "request"}, {"Neem me niet kwalijk", "excuse me"}, {"onderzoek", "research"}, {"overleggen", "to confer, discuss"}, {"Zodra", "as soon as"}, {"vermoeide", "weary (vermoeid)"}, {"voorstellen", "to introduce"}, {"nederige", "humble (nederig)"}, {"dienaar", "servant"}, {"onder ons te houden", "to keep between us"} },
},

[3791] = { en = "The Mystery of Morrowgrain", tier = 4,
  t = "Het mysterie van morrowgrain",
  d = "Ik zal eerlijk tegen je zijn, $N. Ik ben benieuwd - nee, bezorgd - waarom de Arch Druid in Darnassus de naam en de middelen van de Cenarion Circle gebruikt om enorme hoeveelheden morrowgrain te verzamelen. Ik ben onderzoeker; vloeken zijn mijn specialiteit. Ik heb gehoord dat morrowgrain onder de juiste omstandigheden dezelfde eigenschappen heeft als andere kruiden die in primitieve vloeken worden gebruikt.$B$BIk wil er meer over weten, en ik vraag je om hulp. Breng me tien morrowgrain, dan zal ik zeker goed voor je zorgen.",
  o = "Breng 10 Morrowgrain naar Quintis Jonespyre in Feathermoon Stronghold.",
  p = "Ik zoek tien morrowgrain - dat moet genoeg zijn om mijn onderzoek in elk geval te beginnen. Ik zal er ongetwijfeld veel verbruiken op verkeerde sporen, maar zo gaat dat nu eenmaal bij onderzoek.",
  c = "Bah, door deze morrowgrain voel ik me... raar. Wat is Staghelm in de naam van Elune met deze dingen van plan?$B$BMaar goed, nogmaals bedankt voor je hulp. Hier is iets kleins... je weet wel, voor de moeite. Mijn onderzoek naar morrowgrain gaat even duren, en ik heb er ongetwijfeld meer nodig. Nu ik toch bezig ben, kan ik meteen kijken of morrowgrain nuttige toepassingen in de alchemie heeft. Toch voel ik me ongemakkelijk als ik er alleen al in de buurt ben.",
  g = { {"benieuwd", "curious"}, {"bezorgd", "worried, concerned"}, {"middelen", "resources (middel)"}, {"hoeveelheden", "amounts (hoeveelheid)"}, {"vloeken", "curses (vloek)"}, {"omstandigheden", "conditions (omstandigheid)"}, {"eigenschappen", "qualities (eigenschap)"}, {"kruiden", "herbs (kruid)"}, {"ongetwijfeld", "no doubt"}, {"verbruiken", "to use up"}, {"sporen", "paths, tracks (spoor)"}, {"van plan", "up to, planning"}, {"toepassingen", "uses, applications (toepassing)"}, {"ongemakkelijk", "uncomfortable"} },
},

[5092] = { en = "Clear the Way", tier = 4,
  t = "Maak de weg vrij",
  d = "De westelijke en noordelijke wegen naar Andorhal zijn goed versterkt. Daarom wil ik de stad aanvallen via de oostelijke weg, die minder goed verdedigd wordt. De Scourge vertrouwt op de buffer van ondoden die Sorrow Hill teistert als eerste verdedigingslinie. Als we op Andorhal willen oprukken, moeten we dat via Sorrow Hill doen.$B$BJe eerste opdracht is om de weg door Sorrow Hill vrij te maken. Dun de skeletten en ghouls uit die daar rondspoken. Kom bij mij terug als dat gelukt is!",
  o = "Dood 10 Skeletal Flayers en 10 Slavering Ghouls in Sorrow Hill.$B$BGa terug naar Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.",
  p = "Ik wil dat je je op het ergste voorbereidt, $N - zet alles op alles. De taak die voor ons ligt, wordt niet makkelijk. Terwijl we hier onze troepen verzamelen om uiteindelijk de Scourge aan te vallen, maak jij deel uit van onze voorhoede die de strijd naar hen toe brengt! Je missie in Sorrow Hill is het begin van onze weg naar de overwinning!",
  c = "Missie geslaagd, $N! Goed gedaan, goed gedaan.$B$BLaat me je werk tot nu toe belonen met wat munten uit de schatkist van Stormwind. Ik raad je aan om ze te besteden aan uitrusting die je helpt bij je volgende missie... een missie die je naar de ruïnes van Andorhal zelf brengt.$B$BWees klaar! Wees waakzaam!",
  g = { {"versterkt", "fortified (versterken)"}, {"verdedigd", "defended (verdedigen)"}, {"vertrouwt op", "relies on (vertrouwen op)"}, {"teistert", "infests, plagues (teisteren)"}, {"verdedigingslinie", "line of defense"}, {"oprukken", "to advance"}, {"Dun", "thin out (uitdunnen)"}, {"rondspoken", "haunt (rondspoken)"}, {"zet alles op alles", "dig deep, give it everything"}, {"voorhoede", "advance force, vanguard"}, {"geslaagd", "accomplished, successful (slagen)"}, {"schatkist", "coffers, treasury"}, {"uitrusting", "equipment, materiel"}, {"waakzaam", "vigilant"} },
},

[3792] = { en = "Morrowgrain to Feathermoon Stronghold", tier = 4,
  t = "Morrowgrain naar Feathermoon Stronghold",
  p = "Hallo weer, $N. Mijn onderzoek gaat redelijk goed, maar als je nog vijf Morrowgrain hebt, neem ik ze graag van je over. Nou ja... 'graag' is hier bij wijze van spreken; hoe vaker ik in hun buurt ben, hoe ongemakkelijker ik me voel. Toch vraagt mijn onderzoek dat ik doorzet en dit afmaak.",
  c = "Bedankt, $N; ik berg deze voorlopig even op. Ik heb niet de middelen die Staghelm heeft, maar ik kan je wel iets kleins geven voor de moeite. Hoe dan ook, wie weet wat er gebeurt als Staghelm morrowgrain na morrowgrain blijft krijgen. Er is iets niet pluis, let op mijn woorden.$B$BOnthoud dat ik altijd op zoek ben naar meer Morrowgrain. Ik neem ze per vijf tegelijk aan.",
  g = { {"redelijk", "fairly, reasonably"}, {"neem ik ze graag van je over", "I'll gladly take them off your hands (overnemen)"}, {"bij wijze van spreken", "figuratively speaking"}, {"ongemakkelijker", "more uncomfortable (ongemakkelijk)"}, {"doorzet", "persevere, buckle down (doorzetten)"}, {"berg", "store (opbergen)"}, {"voorlopig", "for the time being"}, {"niet pluis", "fishy, not right"}, {"let op mijn woorden", "mark my words"}, {"tegelijk", "at a time, at once"} },
},

[5533] = { en = "Scholomance", tier = 4,
  t = "De Scholomance",
  d = "Op het eiland Caer Darrow ligt Scholomance: een ellendig centrum van necromantie en kwaad van de Scourge. Onze vijand woont daarbinnen en pleegt onuitsprekelijke, verdorven daden tegen nietsvermoedende slachtoffers... dat vermoeden we tenminste. Een deur verspert de weg, en hoe we het ook proberen, zonder de juiste sleutel komt niemand binnen.$B$BAlchemist Arbington weet veel over Scholomance en heeft een idee hoe we een sleutel kunnen krijgen. Je hebt je waarde voor mij bewezen, en nu vertrouw ik deze taak aan jou toe. Praat met hem hierover.",
  o = "Praat met Alchemist Arbington in Chillwind Point, Western Plaguelands.",
  c = "Gegroet, $c. Ik heb een flink deel van mijn recente studies aan de Scholomance besteed, en ik denk dat ik weet hoe je een sleutel kunt krijgen... een sleutel waarmee je langs de voordeur komt.$B$BIk kan me alleen maar voorstellen welke afschuwelijke dingen je daarbinnen te zien krijgt, $N. Ik weet soms niet hoe jullie helden het doen...",
  g = { {"ellendig", "wretched"}, {"necromantie", "necromancy"}, {"pleegt", "commits (plegen)"}, {"onuitsprekelijke", "unspeakable (onuitsprekelijk)"}, {"verdorven", "depraved"}, {"nietsvermoedende", "unwitting, unsuspecting (nietsvermoedend)"}, {"slachtoffers", "victims (slachtoffer)"}, {"vermoeden", "to suspect, surmise"}, {"verspert", "bars, blocks (versperren)"}, {"bewezen", "proved (bewijzen)"}, {"vertrouw", "entrust (toevertrouwen)"}, {"Gegroet", "well met, greetings"}, {"afschuwelijke", "horrid (afschuwelijk)"} },
},

[7907] = { en = "Darkmoon Beast Deck", tier = 4,
  t = "Het Darkmoon Beast Deck",
  d = "Nu je alle Beast-kaarten tot een stapel hebt verzameld, verschijnt er op mysterieuze wijze een negende kaart met dezelfde achterkant als de eerste acht. Op deze kaart staat geschreven: „Breng deze kaarten terug naar de Darkmoon Faire en word beloond.” Je hebt gehoord dat deze kermis om de paar maanden afwisselend in Mulgore en Goldshire staat, dus je moet wachten tot ze hier weer is.",
  o = "Breng het Beast Deck terug naar de Darkmoon Faire als die in de buurt is.",
  p = "O jee.",
  c = "Nou, dat verklaart een hoop. Als je ooit een weg naar Ahn'Qiraj vindt, kijk dan uit naar de oude Brann. Ik ben bang dat hij machteloos is zonder zijn aap.",
  g = { {"stapel", "deck, stack"}, {"op mysterieuze wijze", "mysteriously"}, {"achterkant", "back, backing"}, {"kermis", "fair, carnival"}, {"afwisselend", "alternately"}, {"O jee", "oh dear"}, {"verklaart", "explains (verklaren)"}, {"kijk ... uit naar", "keep an eye out for (uitkijken naar)"}, {"machteloos", "powerless"} },
},

[7927] = { en = "Darkmoon Portals Deck", tier = 4,
  t = "Het Darkmoon Portals Deck",
  d = "Nu je alle Portal-kaarten tot een stapel hebt verzameld, verschijnt er op mysterieuze wijze een negende kaart met dezelfde achterkant als de eerste acht. Op deze kaart staat geschreven: „Breng deze kaarten terug naar de Darkmoon Faire en word beloond.” Je hebt gehoord dat deze kermis om de paar maanden afwisselend in Mulgore en Goldshire staat, dus je moet wachten tot ze hier weer is.",
  o = "Breng het Portals Deck terug naar de Darkmoon Faire als die in de buurt is.",
  p = "Ik zie dat het je gelukt is om een stapel portalen compleet te maken! Gefeliciteerd!",
  c = "Dus je hebt een stapel Portals samengesteld. Door die aan ons terug te geven, ontstaat er een band tussen jou en de Darkmoon die niet snel vergeten wordt. Sta me toe je een van de grotere darkmoon-kaarten te geven, als klein teken van onze waardering.",
