[5097] = { en = "All Along the Watchtowers", tier = 4,
  t = "Langs alle wachttorens",
  d = "Met een magisch apparaat dat Beacon Torch heet, kunnen we doelen die we zelf kiezen markeren voor latere acties van onze troepen. Wat dat betreft: we denken dat de Scourge de wachttorens van Andorhal gebruikt om hun troepenbewegingen te sturen.$B$BJe missie: breek door de verdediging van Andorhal en plaats bakens bij alle vier de wachttorens. Je moet in de deuropening van elke toren staan om het baken te plaatsen; daarna markeert het de toren. De Beacon Torch heeft maar vijf ladingen, dus gebruik ze verstandig!",
  o = "Markeer met de Beacon Torch elke toren in Andorhal; je moet in de deuropening van de toren staan om hem te markeren.$B$BAls alle vier de torens gemarkeerd zijn, breng je de Beacon Torch terug naar Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.",
  p = "Zodra de torens gemarkeerd zijn, worden ze doelen met de hoogste prioriteit voor onze aanval op Andorhal. Ik vermoed dat de grootste dreiging van Andorhal tevoorschijn komt zodra we de torens uitschakelen. Vanaf dat moment wordt het een open gevecht om de macht over de stad!$B$BJe bent terug om succes te melden, toch? Vergeet de Beacon Torch ook niet; we moeten onze uitrusting onder controle houden.",
  c = "Mijn priesters melden dat onze bakenzoekers bij alle vier de torens extreem sterke signalen opvangen! Ik durf het bijna niet te zeggen, maar ik geloof dat je weer een missie met volledig en totaal succes hebt uitgevoerd! Weer goed gedaan, $N!$B$BNu de torens gemarkeerd zijn, zijn onze voorbereidingen voor de aanval klaar. Het is tijd om de strijd naar de Scourge te brengen!",
  o1 = "Toren één gemarkeerd",
  o2 = "Toren twee gemarkeerd",
  o3 = "Toren drie gemarkeerd",
  o4 = "Toren vier gemarkeerd",
  g = { {"wachttorens", "watchtowers (wachttoren)"}, {"markeren", "to mark"}, {"troepenbewegingen", "troop movements"}, {"bakens", "beacons (baken)"}, {"deuropening", "doorway"}, {"ladingen", "charges (lading)"}, {"verstandig", "wisely"}, {"prioriteit", "priority"}, {"dreiging", "threat"}, {"tevoorschijn komt", "emerges (tevoorschijn komen)"}, {"uitschakelen", "to neutralize, switch off"}, {"bakenzoekers", "beacon trackers (bakenzoeker)"}, {"opvangen", "to pick up (signals)"}, {"voorbereidingen", "preparations (voorbereiding)"} },
},

[5537] = { en = "Skeletal Fragments", tier = 4,
  t = "Skeletfragmenten",
  d = "De sleutel van Scholomance heet een Skeleton Key. Hij moet gesmeed worden uit de resten van een skelet - eigenlijk van meerdere - en in een geschikte mal gehard worden met alleen de sterkste metalen. Een machtszegel van een wezen dat van nature de poort naar Scholomance kan openen, zorgt ervoor dat de sleutel uiteindelijk werkt.$B$BMaar eerst het belangrijkste, $N. We hebben skeletfragmenten nodig om de sleutel te smeden. De skeletten in Andorhal zouden moeten opleveren wat we nodig hebben, maar die buiten de muren werken misschien ook.",
  o = "Breng 15 Skeletal Fragments naar Alchemist Arbington in Chillwind Point, Western Plaguelands.",
  p = "Hoe luguber het ook klinkt, we hebben een flinke voorraad geschikte skeletfragmenten nodig voor de buitenlaag van de sleutel. Ze noemen het niet voor niets een Skeleton Key, weet je.",
  c = "Hier kan ik mee werken, $N! Nu is het mijn beurt: ik geef deze fragmenten een geschikte hardheid, zodat ze het zware smeedproces overleven dat ze later zullen doormaken.$B$BDe volgende stap is een goede mal voor de sleutel. Ik ken een goblinsmid in Tanaris die vroeger mallen heeft gemaakt voor soortgelijke macabere voorwerpen. Hij werkt voor degene voor wie goblins meestal werken: de hoogste bieder.",
  g = { {"gesmeed", "forged (smeden)"}, {"resten", "remains (rest)"}, {"geschikte", "suitable (geschikt)"}, {"mal", "mold"}, {"gehard", "hardened (harden)"}, {"machtszegel", "signet of power"}, {"van nature", "naturally"}, {"opleveren", "to yield"}, {"luguber", "morbid"}, {"voorraad", "supply"}, {"buitenlaag", "outer layer"}, {"niet voor niets", "not for nothing"}, {"hardheid", "temper, hardness"}, {"smeedproces", "forging process"}, {"soortgelijke", "similar (soortgelijk)"}, {"macabere", "macabre (macaber)"}, {"bieder", "bidder"} },
},

[5538] = { en = "Mold Rhymes With...", tier = 4,
  t = "Mal rijmt op...",
  d = "De goblin met wie je moet praten, heet Krinkle Goodsteel. Hij verkoopt zijn vaardigheden aan de hoogste bieder in Gadgetzan, in de woestijn van Tanaris. Hij is waarschijnlijk de enige die de mal kan maken die we nodig hebben, en zijn diensten zullen niet goedkoop zijn. We vragen je nu om diep in de buidel te tasten en het bedrag te betalen dat hij vraagt.$B$BIk ben alchemist, geen bankier. Als ik goud had liggen, zat ik hier echt niet.$B$BIk zei weer hardop wat ik eigenlijk had moeten verzwijgen, denk ik. Oeps.$B$BGadgetzan wacht op je! Veel succes!",
  o = "Breng de Imbued Skeletal Fragments en 15 gouden munten naar Krinkle Goodsteel in Gadgetzan.",
  p = "Ja, ik weet wie je bent, en ik weet waarom je hier bent. Arbington heeft me een bericht gestuurd voordat je aankwam. Laten we meteen ter zake komen, goed?$B$BIk heb een mal die je voor de Skeleton Key kunt gebruiken, maar die gaat je wat kosten: vijftien goud, vooraf, en er valt niet over te onderhandelen. Ik stop de skeletfragmenten voor je in de mal, en ik leer je ook hoe je de schacht van de sleutel smeedt zonder dat je iets van smeden weet... en dat nog gratis ook.$B$BWie zegt er dat huurlingen geen scherpe prijzen bieden!",
  c = "Arbington zei al dat je zou leveren, en dat heb je gedaan! Afspraak is afspraak; ik stop de fragmenten voor je in de mal.$B$BHeeft Arbington ze al behandeld? Uitstekend... anders had je een lange reis terug naar Chillwind Point moeten maken.",
  g = { {"rijmt", "rhymes (rijmen)"}, {"vaardigheden", "skills (vaardigheid)"}, {"bieder", "bidder"}, {"diensten", "services (dienst)"}, {"diep in de buidel te tasten", "to dig deep (into your purse)"}, {"bedrag", "amount, fee"}, {"hardop", "out loud"}, {"verzwijgen", "to keep quiet about"}, {"ter zake komen", "to get to the point"}, {"vooraf", "up front"}, {"onderhandelen", "to negotiate"}, {"schacht", "stem, shaft"}, {"huurlingen", "mercenaries (huurling)"}, {"scherpe prijzen", "competitive prices"}, {"Afspraak is afspraak", "a deal is a deal"}, {"behandeld", "treated (behandelen)"} },
},

[5505] = { en = "The Key to Scholomance", tier = 4,
  t = "De sleutel van Scholomance",
  p = "Nou, hier is hij dan, $n: de voltooide Skeleton Key. Ik ben er zo zeker van als ik maar kan zijn dat je met deze sleutel binnen de muren van de Scholomance kunt komen. Er is maar één manier om er helemaal zeker van te zijn dat hij werkt. Verlies geen tijd en probeer hem uit, zou ik zeggen.",
  c = "Veel succes, machtige held. Mogen je overwinningen je roem en macht blijven brengen terwijl je Scholomance verwoest!",
  g = { {"voltooide", "completed (voltooien)"}, {"zo zeker als ik maar kan zijn", "as certain as I can be"}, {"binnen de muren", "within the confines"}, {"Verlies geen tijd", "waste no time"}, {"machtige", "mighty (machtig)"}, {"Mogen", "may (wish)"}, {"overwinningen", "victories (overwinning)"}, {"roem", "fame"}, {"verwoest", "lay waste to (verwoesten)"} },
},

[7881] = { en = "Carnival Boots", tier = 4,
  t = "Laarzen voor de kermis",
  p = "Wij van de Darkmoon Faire lopen heel veel. We lopen van de ene kermisplek naar de andere... je zult ons zelfs nooit zien zitten tijdens het werk! Het is dus geen verrassing dat we heel wat laarzen verslijten! We hebben laarzen nodig die zowel stevig als stijlvol zijn, en Embossed Leather Boots voldoen daar heel goed aan.$B$BJij daar! Jij bent leerbewerker; maak Embossed Leather Boots voor me, dan geef ik je een Darkmoon Faire Ticket voor het werk.",
  c = "Dank je wel, $N. Deze zijn heel goed gemaakt. Het vakmanschap is van topkwaliteit! Hier is een Darkmoon Faire Ticket... veel plezier, $gmeneer:mevrouw;.",
  g = { {"kermis", "fair, carnival"}, {"kermisplek", "fair site"}, {"verrassing", "surprise"}, {"verslijten", "wear out"}, {"stevig", "sturdy, durable"}, {"stijlvol", "stylish"}, {"voldoen daar heel goed aan", "fit that bill well (voldoen aan)"}, {"leerbewerker", "leatherworker"}, {"vakmanschap", "craftsmanship"}, {"topkwaliteit", "top quality"} },
},

[7882] = { en = "Carnival Jerkins", tier = 4,
  t = "Wambuizen voor de kermis",
  p = "Onze kermiswerkers doen meer dan afval vegen en haringen inslaan! Ze helpen ook de kermis te bewaken als die op reis is, en daarom hebben ze altijd goede, stevige wambuizen nodig.$B$BAls je wat Tough Leather Armor maakt en naar mij brengt, zorg ik dat het bij de juiste mensen komt. Ik geef je er ook wat Darkmoon Faire Tickets voor in ruil.",
  c = "Ah, je hebt de wambuizen meegebracht. Prachtig. Van welk dier heb je de huid gebruikt om deze te maken, als ik vragen mag? Het stikwerk is heel goed gedaan, en de structuur van het leer heeft een ruige stijl. Ik zie dat je een vakman bent!$B$BDank je wel, $N, en hier zijn je tickets.",
  g = { {"Wambuizen", "jerkins (wambuis)"}, {"kermiswerkers", "fair workers (kermiswerker)"}, {"afval vegen", "sweep trash"}, {"haringen inslaan", "hammer in tent pegs"}, {"bewaken", "to guard"}, {"stevige", "sturdy (stevig)"}, {"in ruil", "in trade, in exchange"}, {"huid", "skin, hide"}, {"stikwerk", "stitch-work"}, {"structuur", "texture"}, {"ruige", "rugged (ruig)"}, {"vakman", "craftsman"} },
},

[7883] = { en = "The World's Largest Gnome!", tier = 4,
  t = "De grootste gnoom ter wereld!",
  p = "Yebb Nebblegear wil meer talent aan zijn show toevoegen, en hij zoekt overal naar de grootste gnoom ter wereld. Ken jij gnomen van flinke afmetingen?$B$BNou, nog voordat hij de gnoom vindt, wil hij het kostuum al klaar hebben. Ik denk dat een Barbaric Harness een goede basis voor het kostuum is; kun je wat harnassen maken en naar mij brengen? Als je dat doet, heb ik een stapel Darkmoon Faire Tickets voor je...",
  c = "O jee, deze zijn behoorlijk groot!! Ik kan me geen gnoom voorstellen die er precies in past, maar maak je geen zorgen: als de gnoom die we vinden niet groot genoeg is, kan ik zijn kostuum aanpassen.$B$BHeel erg bedankt, $N. Hier zijn de tickets die ik je beloofd had.",
  g = { {"ter wereld", "in the world"}, {"toevoegen", "to add"}, {"afmetingen", "size, dimensions (afmeting)"}, {"kostuum", "costume"}, {"basis", "foundation"}, {"harnassen", "harnesses (harnas)"}, {"stapel", "stack"}, {"behoorlijk", "quite"}, {"maak je geen zorgen", "don't worry"}, {"aanpassen", "to adjust"} },
},

[7884] = { en = "Crocolisk Boy and the Bearded Murloc", tier = 4,
  t = "De crocoliskjongen en de bebaarde murloc",
  p = "Yebb werkt aan andere attracties voor zijn dierentuin, waaronder natte, moerassige verblijven voor een jongen die door crocolisks is opgevoed, en misschien voor een murloc. We hebben mooie, waterdichte beenstukken nodig, zodat we niet doorweekt raken bij het opbouwen en afbreken. Voor dat werk denk ik dat Turtle Scale Leggings het goed zullen doen.$B$B$N, kun jij die beenstukken maken? Als je dat doet, krijg je als beloning een dikke stapel Darkmoon Faire Tickets...",
  c = "Geweldig, je hebt ze gemaakt! Deze zijn prima... ik hoop alleen dat ik niet degene ben die de crocoliskkooi moet schoonmaken als het zover is. Die beesten kunnen behoorlijk beestachtig zijn, vind je niet?$B$BHier zijn je tickets, $N. Veel plezier ermee, en geniet van je verblijf op de Darkmoon Faire!",
  g = { {"bebaarde", "bearded"}, {"attracties", "attractions (attractie)"}, {"dierentuin", "zoo"}, {"moerassige", "swampy (moerassig)"}, {"verblijven", "abodes, enclosures (verblijf)"}, {"opgevoed", "raised (opvoeden)"}, {"waterdichte", "water-tight (waterdicht)"}, {"beenstukken", "leggings (beenstuk)"}, {"doorweekt", "waterlogged, soaked"}, {"opbouwen en afbreken", "setting up and tearing down"}, {"crocoliskkooi", "crocolisk cage"}, {"als het zover is", "when the time comes"}, {"beestachtig", "beastly"}, {"verblijf", "stay"} },
},

[7885] = { en = "Armor Kits", tier = 4,
  t = "Pantserkits",
  p = "Je beseft het misschien niet, maar een reizende kermis runnen is duur! Alles slijt zo snel dat het een wonder is dat we winst maken.$B$BVanwege al die verborgen kosten zoeken we altijd naar manieren om onze uitrusting zo goedkoop mogelijk te onderhouden. Onze tenten scheuren bijvoorbeeld regelmatig, maar ik heb ontdekt dat leren pantserkits prima lappen zijn. Kun je wat pantserkits vinden en naar mij brengen? Dat scheelt ons een flinke smak geld! Als je dat doet, heb ik een handvol Darkmoon Faire Tickets voor je...",
  c = "Geweldig! Dit werkt geweldig! Ik zag net een scheur in een tent daarginds, en zo'n pantserkit is precies wat ik nodig heb om hem te repareren!$B$BHeel erg bedankt, $N. Deze pantserkits besparen ons een hoop reparatiekosten. Hier zijn je tickets - je verdient ze!",
  g = { {"Pantserkits", "armor kits (pantserkit)"}, {"beseft", "realize (beseffen)"}, {"runnen", "to run (a business)"}, {"slijt", "wears down (slijten)"}, {"winst", "profit"}, {"verborgen", "hidden"}, {"onderhouden", "to maintain"}, {"scheuren", "tear (scheuren)"}, {"lappen", "patches (lap)"}, {"scheelt", "saves (schelen)"}, {"een flinke smak geld", "a bundle of money"}, {"handvol", "fistful, handful"}, {"scheur", "rip, tear"}, {"daarginds", "over yonder"}, {"besparen", "to save"} },
},

[7889] = { en = "Coarse Weightstone", tier = 4,
  t = "Ruwe gewichtsteen",
  p = "Het is hard werken om de sterkste vrouw te zijn die er leeft! Mijn set gewichten wordt te licht, en als ik fit wil blijven, heb ik meer gewichten nodig!$B$BDenk je dat je wat gewichtstenen voor me kunt halen? Als je dat doet, geef ik je een Darkmoon Faire Ticket.",
  c = "Geweldig! Deze werken geweldig! Ze zijn niet te zwaar, maar ook niet te licht. Ze zijn perfect om spiermassa op te bouwen!$B$BHartelijk bedankt, $N. Hier is je Darkmoon Faire Ticket!",
  g = { {"Ruwe", "coarse (ruw)"}, {"gewichtsteen", "weightstone"}, {"die er leeft", "alive (who lives)"}, {"gewichten", "weights (gewicht)"}, {"gewichtstenen", "weight stones (gewichtsteen)"}, {"spiermassa", "muscle mass"}, {"op te bouwen", "to build (opbouwen)"}, {"Hartelijk bedankt", "thanks very much"} },
},

[7890] = { en = "Heavy Grinding Stone", tier = 4,
  t = "Zware slijpsteen",
  p = "Voor mijn training steek ik graag een staf tussen zware slijpstenen, en dan til ik de staf boven mijn hoofd. Het is niet makkelijk, maar de sterkste vrouw ter wereld word je niet door te blijven zitten, en dat ben ik!$B$BKun je me helpen? Ik heb meer slijpstenen nodig. Breng me er een paar, dan ruil ik ze voor Darkmoon Faire Tickets.",
  c = "Je hebt de stenen meegebracht! En ze zijn zwaar! Ik voel mijn spieren al groter worden. Bedankt, $N!$B$BHier, neem deze tickets, en eet niet te veel snoep terwijl je op de kermis bent. Een grote, sterke $c zoals jij moet $gzichzelf:zichzelf; in vechtvorm houden!",
  g = { {"slijpsteen", "grinding stone"}, {"steek", "put, fit (steken)"}, {"staf", "staff"}, {"slijpstenen", "grinding stones (slijpsteen)"}, {"til", "lift (tillen)"}, {"ruil", "trade (ruilen)"}, {"spieren", "muscles (spier)"}, {"snoep", "sweets"}, {"kermis", "fair"}, {"vechtvorm", "fighting shape"} },
},

[7891] = { en = "Green Iron Bracers", tier = 4,
  t = "Groene ijzeren armbeschermers",
  p = "Ik werk aan een nieuw kostuum, voor als ik mijn eigen kraam heb als de sterkste vrouw die er leeft! Nu zoek ik armbeschermers die ik kan dragen. Ze mogen niet veel bedekken, want mensen willen mijn spieren zien, maar ik wil toch een beetje kleur laten zien, snap je?$B$BWat dacht je van Green Iron Bracers, $N? Kun je Green Iron Bracers voor me maken? Als dat lukt, heb ik een hele hoop Darkmoon Faire Tickets voor je.",
  c = "Ja! Dit is precies wat ik nodig heb! Zo'n mooie kleur, en mijn armen blijven bloot, zodat je kunt zien hoe sterk ze zijn! Perfect!$B$BAlsjeblieft, $N. Hier zijn je tickets - veel plezier!",
  g = { {"armbeschermers", "bracers (armbeschermer)"}, {"kostuum", "costume"}, {"kraam", "booth"}, {"bedekken", "to cover"}, {"spieren", "muscles (spier)"}, {"snap je", "you know?, get it? (snappen)"}, {"Wat dacht je van", "how about"}, {"een hele hoop", "a whole bunch"}, {"bloot", "bare"} },
},

[7892] = { en = "Big Black Mace", tier = 4,
  t = "Grote zwarte strijdknots",
  p = "Voor mijn act als de sterkste vrouw die er leeft, wil ik voorwerpen van het publiek aannemen en ze kapotslaan met een grote, zwarte strijdknots!$B$BKun je een Big Black Mace voor me maken, $N?",
  c = "Ah, perfect! Deze knots heeft een grote, zware kop. Ik wed dat ik er zo ongeveer alles mee kapot kan slaan. Ik hoop alleen dat hij niet breekt, samen met alles waar ik hem tegenaan zwaai!$B$BHier zijn je tickets, $N. Geniet van je verblijf op de kermis!",
  g = { {"strijdknots", "mace"}, {"act", "act (show)"}, {"voorwerpen", "items (voorwerp)"}, {"publiek", "audience"}, {"kapotslaan", "to smash"}, {"knots", "mace, club"}, {"kop", "head (of a tool)"}, {"wed", "bet (wedden)"}, {"zo ongeveer", "just about"}, {"zwaai", "swing (zwaaien)"}, {"verblijf", "stay"} },
},

[7893] = { en = "Rituals of Strength", tier = 4,
  t = "Rituelen van kracht",
  p = "$N, tijdens mijn zoektocht om de sterkste vrouw te worden die er leeft, ben ik de wereld rondgereisd. Ik heb geheimen voor spieropbouw geleerd van verre gewichtmeesters, krachtgoeroes en oude handboeken. Ik ken nu verboden oefeningen die zwakkelingen zouden doden en onervaren mensen zouden verlammen!$B$BVoor deze krachtprestaties en deze conditietraining moet ik trainen met de dichtste slijpstenen die er zijn. $N, kun je slijpstenen vinden of maken en naar mij brengen? Ik geef je tickets als je dat doet...",
  c = "Dank je wel, $N. Ik ga deze stenen gebruiken in een ritueel om kracht te winnen, dat ik heb geleerd van een oude tablet in de diepste jungles van Stranglethorn.$B$BMen zegt dat zij die deze heilige rite goed uitvoert, de kracht en het uithoudingsvermogen van tien tauren krijgt!",
  g = { {"Rituelen", "rituals (ritueel)"}, {"zoektocht", "quest, search"}, {"rondgereisd", "traveled around (rondreizen)"}, {"spieropbouw", "muscle building"}, {"krachtgoeroes", "strength gurus (krachtgoeroe)"}, {"handboeken", "manuals (handboek)"}, {"zwakkelingen", "weaklings (zwakkeling)"}, {"onervaren", "inexperienced, uninitiated"}, {"verlammen", "to cripple, paralyze"}, {"krachtprestaties", "feats of strength (krachtprestatie)"}, {"conditietraining", "conditioning"}, {"dichtste", "densest (dicht)"}, {"tablet", "(stone) tablet"}, {"rite", "rite"}, {"uithoudingsvermogen", "endurance"} },
},

[7894] = { en = "Copper Modulator", tier = 4,
  t = "Koperen modulator",
  p = "Yebb ontwikkelt een nieuwe attractie voor de Zoo Bizarre, een attractie die mensen gek zal maken van verwondering en plezier! Maar het kost veel werk, en veel materiaal...$B$BDaar horen ook Copper Modulators bij. We hebben heel veel modulators nodig voor de mechanische onderdelen van de attractie. Breng me Copper Modulators, dan ruil ik ze voor een Darkmoon Faire Ticket.",
  c = "Aha! De modulators! Fantastisch!$B$BIk kan je niet precies vertellen wat we bouwen, maar deze zijn onmisbaar voor de bouw ervan. Ik sta bij je in het krijt, $N, maar neem alsjeblieft dit Darkmoon Faire Ticket aan als teken van mijn waardering.",
  g = { {"Koperen", "copper (koper)"}, {"ontwikkelt", "develops (ontwikkelen)"}, {"attractie", "attraction"}, {"verwondering", "wonder"}, {"mechanische", "mechanical (mechanisch)"}, {"onderdelen", "parts (onderdeel)"}, {"onmisbaar", "invaluable, indispensable"}, {"Ik sta bij je in het krijt", "I am in your debt"}, {"teken", "token, sign"}, {"waardering", "appreciation"} },
},

[7895] = { en = "Whirring Bronze Gizmo", tier = 4,
  t = "Zoemend bronzen apparaatje",
  p = "Mijn nieuwe kraam wordt een lust voor het oog, jazeker! Een lust voor het oog, en... voor een paar gelukkigen, ook om aan te raken!$B$BIk hoor de Whirring Bronze Gizmos al hun lied van mechanische vervoering zingen, terwijl bezoekers naar mijn kraam komen en hun vaardigheid testen!$B$BAh... nu heb ik de apparaatjes zelf nodig om mijn droom dichter bij de werkelijkheid te brengen. Alsjeblieft, $N, breng me Whirring Bronze Gizmos... en Darkmoon Faire Tickets worden van jou!",
  c = "Je hebt de apparaatjes meegebracht! Geweldig! Ik hoor hun brommende, zoemende koor nu al in mijn hoofd! O, als deze kraam klaar is, wordt hij het wonder van de wereld, let maar op!$B$BHier zijn je tickets, $N. En geniet alsjeblieft van je verblijf op de kermis!",
  g = { {"Zoemend", "whirring (zoemen)"}, {"apparaatje", "gizmo, little device"}, {"een lust voor het oog", "a sight to see"}, {"jazeker", "yes indeed"}, {"gelukkigen", "lucky ones (gelukkige)"}, {"aan te raken", "to touch (aanraken)"}, {"vervoering", "rapture"}, {"bezoekers", "visitors, patrons (bezoeker)"}, {"vaardigheid", "skill"}, {"werkelijkheid", "reality, fruition"}, {"brommende", "buzzing (brommen)"}, {"koor", "chorus"}, {"let maar op", "mark me, just watch"} },
},

[7896] = { en = "Green Fireworks", tier = 4,
  t = "Groen vuurwerk",
  p = "Als deze kraam eindelijk draait, wil ik reclame maken! En wat is een betere manier om reclame te maken dan met vuurwerk?$B$BNou, sommigen denken misschien dat de geur van een ketel waarin de kokende hoofden van je vijanden ronddraaien beter werkt om mensen te lokken, maar... we zijn hier in gemengd gezelschap. Dus het wordt toch vuurwerk!$B$BBreng me Green Fireworks, $N, dan heb ik een flinke handvol Darkmoon Faire Tickets voor je.",
  c = "Je hebt het vuurwerk meegebracht. Goed gedaan, $N! Ik kan niet wachten om het aan te steken en de wereld te vertellen dat mijn kraam klaar is! Ik moet nog wachten, behoorlijk lang ben ik bang, maar... ik ben klaar als ik klaar ben, toch?$B$BHier zijn de tickets, $N. Veel plezier!",
  g = { {"vuurwerk", "fireworks"}, {"draait", "is up and running (draaien)"}, {"reclame maken", "to advertise"}, {"geur", "smell"}, {"ketel", "cauldron"}, {"kokende", "boiling (koken)"}, {"ronddraaien", "churn, spin around"}, {"lokken", "to draw, lure"}, {"gemengd gezelschap", "mixed company"}, {"handvol", "fistful"}, {"aan te steken", "to light (aansteken)"} },
},

[7897] = { en = "Mechanical Repair Kits", tier = 4,
  t = "Mechanische reparatiekits",
  p = "De belangrijkste reden dat ik mijn kraam niet kan openen, is dat... alles kapot is! Ik heb Mechanical Repair Kits nodig om al die spullen te repareren!$B$BKun je me die kits brengen, $N? Ik ruil met je... kits voor Darkmoon Faire Tickets. Wat zeg je ervan?",
  c = "Dank je wel! Nu kan ik beginnen met repareren.$B$BHet gaat veel reparatiekits en veel late nachten kosten om alles weer werkend te krijgen. Soms denk ik dat het beter zou zijn om terug te gaan naar mijn wortels en mijn carrière als koppensneller opnieuw te beginnen, maar... de kermis is goed voor me geweest.$B$BNeem deze tickets, $N, en veel plezier!",
  g = { {"reparatiekits", "repair kits (reparatiekit)"}, {"kraam", "booth"}, {"spullen", "stuff, things"}, {"ruil", "trade (ruilen)"}, {"Wat zeg je ervan", "what do you say?"}, {"werkend te krijgen", "to get working"}, {"wortels", "roots (wortel)"}, {"carrière", "career"}, {"koppensneller", "headhunter"} },
},

})

